<script setup>
import { Link,useForm } from '@inertiajs/vue3';
const props=defineProps({branch:Object,suppliers:Object});
const form=useForm({name:'',contact_name:'',phone:'',email:'',address:'',notes:''});
function save(){form.post(`/admin/branches/${props.branch.id}/inventory/suppliers`,{preserveScroll:true,onSuccess:()=>form.reset()});}
</script>
<template><main dir="rtl" class="mx-auto max-w-6xl space-y-6 p-4 sm:p-6"><header><Link :href="`/admin/branches/${branch.id}/inventory`" class="text-sm font-bold text-amber-700">المخزون</Link><h1 class="mt-1 text-3xl font-black">الموردون</h1></header><form @submit.prevent="save" class="grid gap-3 rounded-2xl border bg-white p-5 sm:grid-cols-2 lg:grid-cols-3"><h2 class="font-black sm:col-span-2 lg:col-span-3">إضافة مورد</h2><input v-model="form.name" required placeholder="اسم المورد" class="rounded-lg border-slate-300"/><input v-model="form.contact_name" placeholder="اسم مسؤول التواصل" class="rounded-lg border-slate-300"/><input v-model="form.phone" placeholder="الهاتف" class="rounded-lg border-slate-300"/><input v-model="form.email" type="email" placeholder="البريد الإلكتروني" class="rounded-lg border-slate-300"/><input v-model="form.address" placeholder="العنوان" class="rounded-lg border-slate-300"/><button class="rounded-lg bg-slate-900 px-4 py-2 font-bold text-white">حفظ المورد</button></form><section class="overflow-hidden rounded-2xl border bg-white"><div class="border-b p-4 font-black">قائمة الموردين</div><div v-for="s in suppliers.data" :key="s.id" class="flex flex-wrap justify-between gap-2 border-b p-4"><div><p class="font-bold">{{s.name}}</p><p class="mt-1 text-xs text-slate-500">{{s.contact_name||'—'}} · {{s.phone||'—'}} · {{s.email||'—'}}</p></div><span class="text-xs text-slate-500">{{s.is_active?'نشط':'متوقف'}}</span></div><p v-if="!suppliers.data.length" class="p-6 text-sm text-slate-500">لا يوجد موردون مسجلون.</p></section></main></template>
